(()=>{
'use strict';
const DB_NAME='tora-seisou-report';const DB_VERSION=1;const STORE='jobs';
function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(STORE)){const s=db.createObjectStore(STORE,{keyPath:'id'});s.createIndex('updatedAt','updatedAt');s.createIndex('workDate','workDate')}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function tx(mode,fn){const db=await openDb();return new Promise((resolve,reject)=>{const t=db.transaction(STORE,mode),s=t.objectStore(STORE);let result;try{result=fn(s)}catch(e){reject(e)}t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function putJob(job){job.updatedAt=new Date().toISOString();await tx('readwrite',s=>s.put(job));return job}
async function getJob(id){const db=await openDb();return new Promise((res,rej)=>{const r=db.transaction(STORE).objectStore(STORE).get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function allJobs(){const db=await openDb();return new Promise((res,rej)=>{const r=db.transaction(STORE).objectStore(STORE).getAll();r.onsuccess=()=>res(r.result.sort((a,b)=>(b.workDate||'').localeCompare(a.workDate||'')||b.updatedAt.localeCompare(a.updatedAt)));r.onerror=()=>rej(r.error)})}
async function deleteJob(id){await tx('readwrite',s=>s.delete(id))}
async function importJobs(jobs){for(const j of jobs)await putJob(j)}

const AREAS=['キッチン','浴室','洗面','トイレ','玄関','居室','ベランダ','その他'];
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
function emptyJob(){return{id:uid(),client:'',property:'',room:'',address:'',workDate:new Date().toISOString().slice(0,10),worker:'',notes:'',photos:[],defects:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
function escapeHtml(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function searchJobs(jobs,q){q=q.trim().toLowerCase();if(!q)return jobs;return jobs.filter(j=>[j.client,j.property,j.room,j.address,j.worker].some(v=>(v||'').toLowerCase().includes(q)))}
function validateBackup(data){return data&&data.app==='tora-seisou-report'&&Array.isArray(data.jobs)}
function backupPayload(jobs){return{app:'tora-seisou-report',version:1,exportedAt:new Date().toISOString(),jobs}}

function base(title,body){return`<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>@page{size:A4;margin:14mm}body{font-family:"Hiragino Sans","Yu Gothic",sans-serif;color:#142c24;font-size:11pt}h1{font-size:22pt;border-bottom:3px solid #1e513f;padding-bottom:8px}.meta{display:grid;grid-template-columns:1fr 1fr;border:1px solid #aaa}.meta div{padding:7px;border:1px solid #ddd}.photos{display:grid;grid-template-columns:1fr 1fr;gap:8px}.photo{break-inside:avoid;border:1px solid #bbb;padding:6px}.photo img{width:100%;height:180px;object-fit:contain}.area{break-before:auto}table{width:100%;border-collapse:collapse}th,td{border:1px solid #aaa;padding:7px;text-align:left}.page{break-before:page}.muted{color:#666}.no-print{margin:12px;padding:12px;background:#eef4ea}@media print{.no-print{display:none}}</style></head><body><div class="no-print">印刷画面で「PDFとして保存」を選択してください。iPhoneは共有→プリント→プレビューを拡大→共有でPDF保存できます。</div>${body}<script>setTimeout(()=>window.print(),500)<\/script></body></html>`}
function meta(j){return`<div class="meta"><div><b>元請け</b><br>${escapeHtml(j.client)}</div><div><b>作業日</b><br>${escapeHtml(j.workDate)}</div><div><b>物件</b><br>${escapeHtml(j.property)} ${escapeHtml(j.room)}</div><div><b>担当者</b><br>${escapeHtml(j.worker)}</div><div style="grid-column:1/-1"><b>住所</b><br>${escapeHtml(j.address)}</div><div style="grid-column:1/-1"><b>備考</b><br>${escapeHtml(j.notes).replace(/\n/g,'<br>')}</div></div>`}
function cleaningReport(j){const groups=Object.groupBy?Object.groupBy(j.photos,p=>p.area):j.photos.reduce((a,p)=>((a[p.area]??=[]).push(p),a),{});let photos=Object.entries(groups).map(([area,ps])=>`<section class="area"><h2>${escapeHtml(area)}</h2><div class="photos">${ps.map(p=>`<div class="photo"><b>${p.phase==='before'?'ビフォー':'アフター'}</b><img src="${p.dataUrl}"><div>${escapeHtml(p.caption||'')}</div></div>`).join('')}</div></section>`).join('');return base('清掃完了報告書',`<h1>清掃完了報告書</h1>${meta(j)}<h2>作業写真</h2>${photos||'<p>写真なし</p>'}`)}
function defectReport(j){const rows=j.defects.map((d,i)=>`<section class="${i?'page':''}"><h2>不具合 ${i+1}</h2><table><tr><th>箇所</th><td>${escapeHtml(d.place)}</td><th>種別</th><td>${escapeHtml(d.type)}</td></tr><tr><th>対応状況</th><td colspan="3">${escapeHtml(d.status)}</td></tr><tr><th>説明</th><td colspan="3">${escapeHtml(d.description).replace(/\n/g,'<br>')}</td></tr></table>${d.photo?`<p><img src="${d.photo}" style="max-width:100%;max-height:520px"></p>`:''}</section>`).join('');return base('不具合報告書',`<h1>不具合報告書</h1>${meta(j)}${rows||'<p>不具合登録なし</p>'}`)}
function openReport(html){const w=window.open('','_blank');if(!w)throw new Error('ポップアップがブロックされました');w.document.open();w.document.write(html);w.document.close()}

const DRIVE_SCOPE='https://www.googleapis.com/auth/drive.file';
const DRIVE_FILE_PREFIX='とら清掃報告-';

function driveFileName(date=new Date()){
  return `${DRIVE_FILE_PREFIX}${date.toISOString().slice(0,10)}.json`;
}

function driveListUrl(){
  const query="mimeType='application/json' and trashed=false and name contains 'とら清掃報告-'";
  const params=new URLSearchParams({spaces:'drive',orderBy:'createdTime desc',pageSize:'20',fields:'files(id,name,createdTime)',q:query});
  return `https://www.googleapis.com/drive/v3/files?${params}`;
}

function latestDriveBackup(response){
  const files=Array.isArray(response?.files)?response.files:[];
  return files[0]||null;
}

function multipartBackup(payload,name,boundary){
  const meta={name,mimeType:'application/json',appProperties:{application:'tora-seisou-report',schema:'1'}};
  return `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${JSON.stringify(payload)}\r\n--${boundary}--`;
}

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let job=emptyJob(),phase='before',saveTimer,deferredInstall;
const DEFAULT_GOOGLE_CLIENT_ID='532652666507-dtjsrmnmtqpg4n3u2qikgerebojms2lp.apps.googleusercontent.com';
const fields=['client','property','room','address','workDate','worker','notes'];
const toast=m=>{const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
function setSaveState(t){$('#saveState').textContent=t}
function readForm(){for(const f of fields)job[f]=$('#'+f).value;return job}
function fillForm(){for(const f of fields)$('#'+f).value=job[f]||'';$('#jobId').value=job.id;renderPhotos();renderDefects()}
function scheduleSave(){setSaveState('保存中…');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,550)}
async function saveNow(){try{readForm();await putJob(job);setSaveState('保存済み');updateStorage();return true}catch(e){setSaveState('保存失敗');toast('保存できません。空き容量を確認してください');console.error(e);return false}}
function switchView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));if(id==='history')renderHistory();if(id==='settings')updateStorage();scrollTo({top:0,behavior:'smooth'})}
async function imageData(file){if(!file.type.startsWith('image/'))throw new Error('画像ファイルではありません');const img=await createImageBitmap(file);const max=1600,scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.82)}
function photoLabel(p){return p.phase==='before'?'ビフォー':'アフター'}
function renderPhotos(){const root=$('#photoSections');root.innerHTML='';$('#photoCount').textContent=`${job.photos.length}枚`;for(const area of AREAS){const ps=job.photos.filter(p=>p.area===area);if(!ps.length)continue;const sec=document.createElement('section');sec.className='photo-group';sec.innerHTML=`<h2>${area}</h2><div class="photo-grid"></div>`;const grid=sec.querySelector('.photo-grid');ps.forEach(p=>{const i=job.photos.findIndex(x=>x.id===p.id),card=document.createElement('article');card.className='photo-card';card.innerHTML=`<img src="${p.dataUrl}" alt="${area} ${photoLabel(p)}"><div class="photo-meta"><b>${photoLabel(p)}</b><input class="caption" value="${escapeHtml(p.caption||'')}" placeholder="写真メモ"><div class="photo-actions"><button data-act="up">↑</button><button data-act="down">↓</button><button data-act="delete">削除</button></div></div>`;card.querySelector('.caption').oninput=e=>{p.caption=e.target.value;scheduleSave()};card.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{const a=b.dataset.act;if(a==='delete')job.photos.splice(i,1);else{const ni=a==='up'?Math.max(0,i-1):Math.min(job.photos.length-1,i+1);[job.photos[i],job.photos[ni]]=[job.photos[ni],job.photos[i]]}renderPhotos();scheduleSave()});grid.append(card)});root.append(sec)}}
function renderDefects(){const root=$('#defectList');root.innerHTML='';job.defects.forEach(d=>{const n=$('#defectTemplate').content.cloneNode(true),card=n.querySelector('.defect-card');card.dataset.id=d.id;card.querySelector('.defect-place').value=d.place||'';card.querySelector('.defect-type').value=d.type||'破損';card.querySelector('.defect-status').value=d.status||'未対応';card.querySelector('.defect-description').value=d.description||'';if(d.photo)card.querySelector('.defect-preview').innerHTML=`<img src="${d.photo}" alt="不具合写真">`;for(const [sel,key] of [['.defect-place','place'],['.defect-type','type'],['.defect-status','status'],['.defect-description','description']])card.querySelector(sel).oninput=e=>{d[key]=e.target.value;scheduleSave()};card.querySelector('.delete-defect').onclick=()=>{job.defects=job.defects.filter(x=>x.id!==d.id);renderDefects();scheduleSave()};card.querySelector('.defect-photo').onchange=async e=>{try{d.photo=await imageData(e.target.files[0]);renderDefects();scheduleSave()}catch(err){toast(err.message)}};root.append(n)});if(!job.defects.length)root.innerHTML='<div class="card hint">不具合は登録されていません。</div>'}
async function renderHistory(){const jobs=searchJobs(await allJobs(),$('#historySearch').value),root=$('#historyList');root.innerHTML=jobs.length?'':'<div class="card hint">該当する履歴はありません。</div>';for(const j of jobs){const e=document.createElement('article');e.className='card history-item';e.innerHTML=`<div><strong>${escapeHtml(j.property||'名称未入力')} ${escapeHtml(j.room||'')}</strong><p>${escapeHtml(j.workDate||'日付未入力')} / ${escapeHtml(j.client||'元請け未入力')}</p><p>${escapeHtml(j.address||'')}</p></div><div class="stack"><button class="secondary edit">編集</button><button class="danger remove">削除</button></div>`;e.querySelector('.edit').onclick=async()=>{job=await getJob(j.id);fillForm();switchView('editor')};e.querySelector('.remove').onclick=async()=>{if(confirm('この現場と写真を削除しますか？')){await deleteJob(j.id);renderHistory()}};root.append(e)}}
async function updateStorage(){if(!navigator.storage?.estimate){$('#storageInfo').textContent='このブラウザでは容量情報を取得できません';return}const{usage=0,quota=0}=await navigator.storage.estimate(),mb=n=>(n/1048576).toFixed(1);$('#storageInfo').textContent=`使用 ${mb(usage)} MB / 利用可能目安 ${mb(quota)} MB`;if(quota&&usage/quota>.8)toast('保存容量が80%を超えています。バックアップ後に不要な写真を整理してください')}
async function exportBackup(){await saveNow();const data=backupPayload(await allJobs()),blob=new Blob([JSON.stringify(data)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`tora-seisou-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importBackup(file){const data=JSON.parse(await file.text());if(!validateBackup(data))throw new Error('とら清掃報告のバックアップではありません');await importJobs(data.jobs);toast(`${data.jobs.length}件を復元しました`);renderHistory()}
let googleLoadPromise;
function loadGoogle(){if(window.google?.accounts?.oauth2)return Promise.resolve();if(googleLoadPromise)return googleLoadPromise;googleLoadPromise=new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-tora-google]'),s=existing||document.createElement('script'),timer=setTimeout(()=>reject(new Error('Google認証の読み込みがタイムアウトしました')),15000);s.dataset.toraGoogle='1';s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=()=>{clearTimeout(timer);window.google?.accounts?.oauth2?resolve():reject(new Error('Google認証を初期化できません'))};s.onerror=()=>{clearTimeout(timer);reject(new Error('Google認証を読み込めません'))};if(!existing)document.head.append(s)}).catch(e=>{googleLoadPromise=null;throw e});return googleLoadPromise}
async function driveToken(){const clientId=localStorage.getItem('tora_google_client_id')||DEFAULT_GOOGLE_CLIENT_ID;await loadGoogle();return new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:clientId,scope:DRIVE_SCOPE,callback:r=>r.error?reject(new Error(`Google認証失敗: ${r.error}`)):resolve(r.access_token),error_callback:e=>reject(new Error(`Google認証を完了できません: ${e.type||'unknown'}`))});client.requestAccessToken()})}
async function driveBackup(){await saveNow();$('#driveStatus').textContent='Google認証中…';const token=await driveToken(),payload=backupPayload(await allJobs()),name=driveFileName(),boundary='tora_'+Date.now(),body=multipartBackup(payload,name,boundary);$('#driveStatus').textContent='Googleドライブへ保存中…';const res=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,createdTime',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':`multipart/related; boundary=${boundary}`},body});if(!res.ok)throw new Error(`Drive保存失敗 ${res.status}`);const saved=await res.json();$('#driveStatus').textContent=`保存完了：${saved.name||name}`;toast('Googleドライブへ保存しました')}
async function driveRestore(){if(!confirm('Googleドライブの最新バックアップをこの端末へ復元しますか？\n同じIDの現場は更新されます。'))return;$('#driveStatus').textContent='Google認証中…';const token=await driveToken(),headers={Authorization:`Bearer ${token}`},listRes=await fetch(driveListUrl(),{headers});if(!listRes.ok)throw new Error(`Drive一覧取得失敗 ${listRes.status}`);const latest=latestDriveBackup(await listRes.json());if(!latest)throw new Error('このアプリで作成したDriveバックアップがありません');$('#driveStatus').textContent=`復元中：${latest.name}`;const fileRes=await fetch(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(latest.id)}?alt=media`,{headers});if(!fileRes.ok)throw new Error(`Drive復元失敗 ${fileRes.status}`);const data=await fileRes.json();if(!validateBackup(data))throw new Error('Drive上のファイルは、とら清掃報告のバックアップではありません');await importJobs(data.jobs);job=emptyJob();fillForm();await renderHistory();$('#driveStatus').textContent=`復元完了：${latest.name}（${data.jobs.length}件）`;toast(`${data.jobs.length}件をGoogleドライブから復元しました`)}
function bind(){AREAS.forEach(a=>$('#photoArea').add(new Option(a,a)));$$('.tabs button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));fields.forEach(f=>$('#'+f).addEventListener('input',scheduleSave));$('#saveBtn').onclick=async()=>{await saveNow();toast('保存しました')};$('#newJobBtn').onclick=()=>{job=emptyJob();fillForm();toast('新しい現場を作成しました')};$$('[data-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.phase;$$('[data-phase]').forEach(x=>x.classList.toggle('active',x===b))});$('#photoInput').onchange=async e=>{for(const f of e.target.files){try{job.photos.push({id:uid(),area:$('#photoArea').value,phase,dataUrl:await imageData(f),caption:'',createdAt:new Date().toISOString()})}catch(err){toast(err.message)}}e.target.value='';renderPhotos();scheduleSave()};$('#addDefectBtn').onclick=()=>{job.defects.push({id:uid(),place:'',type:'破損',description:'',status:'未対応',photo:null});renderDefects();scheduleSave()};$('#historySearch').oninput=renderHistory;$('#exportBtn').onclick=exportBackup;$('#importInput').onchange=async e=>{try{await importBackup(e.target.files[0])}catch(err){toast(err.message)}};$('#cleaningPdfBtn').onclick=()=>{readForm();openReport(cleaningReport(job))};$('#defectPdfBtn').onclick=()=>{readForm();openReport(defectReport(job))};$('#googleClientId').value=localStorage.getItem('tora_google_client_id')||'';$('#driveStatus').textContent=$('#googleClientId').value?'現在：Client ID設定済み':'現在：未設定';$('#saveGoogleConfig').onclick=()=>{localStorage.setItem('tora_google_client_id',$('#googleClientId').value.trim());$('#driveStatus').textContent=$('#googleClientId').value.trim()?'現在：Client ID設定済み':'現在：未設定';toast('端末内に保存しました')};$('#driveBackupBtn').onclick=()=>driveBackup().catch(e=>{$('#driveStatus').textContent=e.message;toast(e.message)});$('#driveRestoreBtn').onclick=()=>driveRestore().catch(e=>{$('#driveStatus').textContent=e.message;toast(e.message)});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(deferredInstall){deferredInstall.prompt();deferredInstall=null}};window.addEventListener('online',()=>toast('オンラインに戻りました'));window.addEventListener('offline',()=>toast('オフラインです。端末内保存を継続します'))}
async function init(){bind();if(!localStorage.getItem('tora_google_client_id')){$('#googleClientId').value=DEFAULT_GOOGLE_CLIENT_ID;$('#driveStatus').textContent='現在：Client ID設定済み（アプリ既定）'}fillForm();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');updateStorage();window.addEventListener('pagehide',()=>{if(saveTimer)saveNow()})}
init().catch(e=>{console.error(e);toast('起動に失敗しました')});

})();

